# STRATEGY - in a language with first-class functions, the pattern
# is a dictionary. The dropdown above writes nb["pricing_strategy"];
# Python (two-way nb) reads it. Change the controls, re-run this cell.

def flat(n):
    return n * 2.40

def tiered(n):
    price, remaining = 0.0, n
    for band, rate in [(50, 2.40), (150, 1.90), (10**9, 1.45)]:
        take = min(remaining, band)
        price += take * rate
        remaining -= take
        if remaining == 0:
            break
    return price

def member(n):
    return max(n * 2.40 * 0.85, 1.99)

STRATEGIES = {"flat": flat, "tiered": tiered, "member": member}

chosen = nb.get("pricing_strategy") or "tiered"
n = int(nb.get("order_size") or 120)

print(f"order of {n} units, all three strategies:")
for name, fn in STRATEGIES.items():
    marker = "  <-- selected" if name == chosen else ""
    print(f"  {name:7s} {fn(n):9.2f}{marker}")

total = STRATEGIES[chosen](n)
print(f"\ncharged with '{chosen}': {total:.2f}")
print("the calling code never branched on the strategy name - that's the pattern")
nb["order_total"] = round(total, 2)

# BUILDER - assemble a query step by step; validation happens once, at the end.
class QueryBuilder:
    def __init__(self, table):
        self._table = table
        self._wheres = []
        self._order = None
        self._limit = None

    def where(self, cond):
        self._wheres.append(cond)
        return self          # returning self is what makes it fluent

    def order_by(self, col, desc=False):
        self._order = (col, desc)
        return self

    def limit(self, n):
        self._limit = n
        return self

    def build(self):
        if self._limit is not None and self._limit <= 0:
            raise ValueError("limit must be positive")
        sql = f"SELECT * FROM {self._table}"
        if self._wheres:
            sql += " WHERE " + " AND ".join(self._wheres)
        if self._order:
            sql += f" ORDER BY {self._order[0]}" + (" DESC" if self._order[1] else "")
        if self._limit:
            sql += f" LIMIT {self._limit}"
        return sql

q = (QueryBuilder("orders")
     .where("total > 100")
     .where("status = 'paid'")
     .order_by("created_at", desc=True)
     .limit(20)
     .build())
print(q)

try:
    QueryBuilder("orders").limit(0).build()
except ValueError as e:
    print("builder refused a broken query:", e)

