// OBSERVER - the entire pattern is ~15 lines.
class EventBus {
  constructor() { this.subscribers = {}; }
  on(topic, fn) {
    (this.subscribers[topic] = this.subscribers[topic] || []).push(fn);
    return () => {   // unsubscribe is part of the pattern people forget
      this.subscribers[topic] = this.subscribers[topic].filter(f => f !== fn);
    };
  }
  emit(topic, data) {
    (this.subscribers[topic] || []).forEach(fn => fn(data));
  }
}

const bus = new EventBus();
const log = [];

const offAudit = bus.on('order', o => log.push('audit:   recorded ' + o.total));
bus.on('order', o => log.push('email:   receipt for ' + o.total));
bus.on('refund', o => log.push('finance: refund of ' + o.total));

bus.emit('order', { total: nb.get('order_total') || 288.0 });
bus.emit('refund', { total: 12.5 });

offAudit();                 // audit unsubscribes...
bus.emit('order', { total: 99 });   // ...and misses this one

log.forEach(l => console.log(l));
console.log();
console.log('emitters never name their listeners - same contract as nb.onChange.');
console.log('the notebook bridge is an EventBus whose topics are variable names.');
return { deliveries: log.length, pattern: 'observer' };
